const _pick=(arr,n)=>[...arr].sort(()=>Math.random()-0.5).slice(0,n);
const _shuffle=(arr)=>[...arr].sort(()=>Math.random()-0.5);

// ══════════ Formas deterministas (el estándar de M.E.T.A.S) ══════════
// El número de forma NO es decorativo: es la semilla. La Forma 7 saca hoy y
// dentro de un año exactamente las mismas preguntas, en el mismo orden y con
// la misma pauta, en este aparato y en cualquier otro. Eso es lo que permite
// imprimir una prueba, guardar su pauta y que sigan coincidiendo.
// Antes se barajaba con Math.random() y se contaba 1..10 aparte, así que dos
// impresiones de la «Forma 3» eran pruebas distintas con el mismo rótulo.
const EVAL_FORMAS = 30;
function _evalRng(forma) {
  let s = (forma * 2654435761 + 909090909) >>> 0;
  return function () {
    s = (s + 0x6D2B79F5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const _shuffleF = (arr, rng) => { const a = [...arr]; for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); const tmp = a[i]; a[i] = a[j]; a[j] = tmp; } return a; };
const _pickF = (arr, n, rng) => _shuffleF(arr, rng).slice(0, n);
// Para las secciones que sacan UN solo caso: barajar con semilla no garantiza
// que todos salgan. Con 8 casos y 30 formas, alguno no aparece nunca y se
// vuelve contenido muerto. La rotación por número de forma es igual de
// determinista y sí recorre el banco entero.
const _rotaF = (arr, forma) => arr[(forma - 1) % arr.length];
function _injectFormaSel(fnName, selId, actual, onPick) {
  const ya = document.getElementById(selId);
  if (ya) { ya.value = String(actual); return; }
  const btn = document.querySelector('[onclick*="' + fnName + '()"]');
  if (!btn || !btn.parentNode) return;
  const wrap = document.createElement('label');
  wrap.style.cssText = 'display:inline-flex;align-items:center;gap:6px;margin:0 8px 6px 0;font-weight:700;font-size:0.95rem;';
  let ops = '';
  for (let i = 1; i <= EVAL_FORMAS; i++) ops += '<option value="' + i + '"' + (i === actual ? ' selected' : '') + '>Forma ' + i + '</option>';
  wrap.innerHTML = '📋 <select id="' + selId + '" style="padding:6px 10px;border-radius:8px;border:2px solid #888;font-weight:700;font-size:0.95rem;background:#fff;color:#222;" aria-label="Elegir número de forma exacta (1 a ' + EVAL_FORMAS + ')">' + ops + '</select>';
  btn.parentNode.insertBefore(wrap, btn);
  const sel = wrap.querySelector('select');
  if (sel) sel.addEventListener('change', function () { onPick(parseInt(this.value, 10) || 1); try { saveProgress(); } catch (e) { } });
}
function _evalFormaSelector() { _injectFormaSel('genEval', 'evalFormaSel', evalFormNum, function (v) { evalFormNum = v; }); }
