const identifyTaskDB=[{"s":"La versión que su autor firmaría.","type":"El hombre de acero"},{"s":"El muñeco flojo para tumbar fácil.","type":"El hombre de paja"},{"s":"Exponer sin que un defensor te distinga.","type":"La prueba de Turing ideológica (Caplan)"},{"s":"El modo de producir condiciona las ideas.","type":"El materialismo histórico"},{"s":"El excedente y quién se lo apropia.","type":"La teoría de la explotación"},{"s":"Niños en minas, con informes de inspectores.","type":"La fuerza moral documentada"},{"s":"Allen 2003 y Sen, con etiqueta de disputa.","type":"Los números del acero"},{"s":"Diez minutos de pie sin corrección.","type":"La licencia de la etapa"},{"s":"El dato que alegra paga doble auditoría.","type":"La regla del placer"},{"s":"Dos expedientes gemelos o ninguno.","type":"La báscula pareja"}];
const classifyTaskDB=[{"w":"El hombre de acero","gen":"Herramienta","n":"La versión que su autor firmaría","g":"Antes de todo juicio","t":"Regla de la casa"},{"w":"El hombre de paja","gen":"Vicio","n":"El muñeco flojo de los panfletos","g":"Los dos púlpitos","t":"Falacia remitida a su materia"},{"w":"La prueba de Turing ideológica","gen":"Ejercicio","n":"Que un defensor no te distinga","g":"Caplan, divulgación","t":"No es medida validada"},{"w":"El manifiesto comunista (1848)","gen":"Fuente primaria","n":"Entra en resumen de trabajo","g":"Su dueña es otra materia","t":"Resumen, no relectura"},{"w":"El capital, tomo I (1867)","gen":"Fuente primaria","n":"La explotación con definiciones","g":"Su dueña es otra materia","t":"Resumen, no relectura"},{"w":"Singer, breve introducción","gen":"Divulgación","n":"La escalera corta al resumen fuerte","g":"Biblioteca de la etapa","t":"Divulgación sólida"},{"w":"Farm to Factory (Allen, 2003)","gen":"Defensa empírica","n":"La industrialización con datos","g":"Números del acero","t":"Disputa viva"},{"w":"Sen, China-India","gen":"Comparación","n":"Salud básica antes de la reforma","g":"Números del acero","t":"Académico sólido"},{"w":"La regla del placer","gen":"Vigilancia","n":"La alegría como alarma","g":"El cuaderno propio","t":"Doble auditoría"},{"w":"La defensa detenida","gen":"Protocolo","n":"La mano alzada sin drama","g":"La mesa de la casa","t":"Se repite otro día"}];
const completeTaskDB=[{"s":"La regla de la casa: primero el acero, después la ___.","opts":["respuesta","burla","nota"],"ans":"respuesta"},{"s":"Nadie audita lo que no puede ___.","opts":["enunciar","comprar","ver"],"ans":"enunciar"},{"s":"El resumen fuerte lo firmaría un ___.","opts":["marxista","rival","juez"],"ans":"marxista"},{"s":"La prueba de Turing es un ejercicio, no una medida ___.","opts":["validada","divertida","rápida"],"ans":"validada"},{"s":"Los informes de inspectores documentaban las ___.","opts":["minas","fiestas","ventas"],"ans":"minas"},{"s":"Allen defiende la industrialización con ___.","opts":["datos","banderas","poemas"],"ans":"datos"},{"s":"Los expedientes gemelos se archivan ___.","opts":["juntos","separados","nunca"],"ans":"juntos"},{"s":"La licencia son diez minutos de ___.","opts":["pie","video","lectura"],"ans":"pie"}];
const explainQuestions=[{"q":"¿Por qué ninguna crítica empieza sin el acero? Explícalo con la imagen del ajedrecista que entrena solo.","ans":"Porque refutar una versión que nadie firma es ganarle a nadie. El ajedrecista que entrena solo mueve flojas las piezas del rival y se vuelve invencible contra un fantasma; el día del torneo real descubre que nunca jugó de verdad. Lo mismo pasa con las doctrinas: quien solo conoce la caricatura del panfleto lleva años ganando sobremesas y no ha tocado el sistema real, que sigue intacto y sin auditar. El acero (la versión que su autor firmaría) es apuntarle al blanco de verdad: solo esa victoria cuenta, y solo esa derrota enseña."},{"q":"Enuncia las cuatro piezas del resumen fuerte como las firmaría un marxista.","ans":"Una: el materialismo histórico como programa de investigación: el modo en que una sociedad produce su vida material condiciona sus instituciones y sus ideas. Dos: la teoría de la explotación: el excedente lo produce el trabajo y se lo apropia el dueño de los medios de producción. Tres: la tendencia a la crisis: el sistema produce sus propias sacudidas periódicas. Cuatro: la promesa de la sociedad sin clases, que ordena el edificio entero. Enunciadas así, sin burla y en su vocabulario, un defensor diría «así es»: esa es la señal de que hay acero y no muñeco."},{"q":"¿Qué es la prueba de Turing ideológica, de quién es, y con qué etiqueta se usa?","ans":"Es el ejercicio de exponer una doctrina ajena de modo que un defensor no distinga al alumno de uno de los suyos. La propuso Bryan Caplan, y la casa la usa con su etiqueta exacta: concepto de divulgación, útil como ejercicio, no una medida validada; la herramienta se fabrica en Estudio de las Ideologías y aquí se corre como estación primera. Pasarla no significa estar de acuerdo: significa que la crítica que venga después apuntará al sistema real y no a la caricatura, que es la única manera de que el veredicto valga algo."},{"q":"¿Por qué el acero incluye la fuerza moral y los números, y no solo la teoría?","ans":"Porque un sistema sin su fuerza moral es otro hombre de paja. Marx no vendía un cielo: señalaba niños en minas con informes de inspectores ingleses en la mano, y esa indignación documentada explica siglo y medio de lealtades; omitirla deja el sistema como capricho sin causa. Y el acero de un sistema con Estado incluye sus mejores números: la industrialización que Allen defiende con datos (2003, disputa viva), los saltos de alfabetización y salud, el cotejo de Sen entre China y la India en salud básica. Entran con su etiqueta, y el módulo de los tres expedientes los pesará después contra sus costos: ponerlos en pie no es absolver, es pesar completo."},{"q":"¿Qué es la regla del placer y por qué el remedio es de procedimiento y no de voluntad?","ans":"La regla dice: si un dato te alegra porque hunde al bando contrario, paga doble auditoría (horquilla, método, fuente y contracrítica) antes de entrar al cuaderno. Es de procedimiento porque la evidencia sobre el sesgo de mi lado muestra que el detector de trampas se afina solo hacia el rival: proponerse ser imparcial no alcanza, igual que proponerse no tener sed no hidrata. Por eso la casa no confía en la voluntad: instala el procedimiento fijo, y el argumento propio pasa por las mismas preguntas críticas que el ajeno."},{"q":"¿Por qué esta materia se estudia en pares con el Expediente Dorado?","ans":"Porque el acero de esta casa se mide en pares: la Crítica al Marxismo y la Crítica al Capitalismo comparten esqueleto módulo a módulo, y la Bóveda no acepta un expediente sin el otro. La razón es la misma báscula: quien audita con dureza solo al sistema que le disgusta no está auditando, está militando con notas al pie. El test del espejo lo dice en una pregunta: ¿aceptarías este argumento, esta cifra o esta oferta si viniera del bando contrario? Si la respuesta es no, el problema no es el bando: es la báscula."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> La versión que su autor firmaría. → <span style="color:var(--jade);font-weight:700;">El hombre de acero</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

