// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1848","icon":"📜","label":"El Manifiesto","text":"Marx y Engels publican <strong>El manifiesto comunista</strong>: la promesa de la sociedad sin clases y la historia como pleito de clases. <strong>Aquí entra en resumen de trabajo:</strong> el entero vive en sus materias dueñas."},{"y":"1860s","icon":"⛏️","label":"Los informes","text":"Los <strong>inspectores fabriles ingleses</strong> documentan niños en minas y fábricas. Marx los usa como munición: <strong>la fuerza moral del sistema es indignación documentada</strong>, no promesa de cielo, y el acero la incluye."},{"y":"1867","icon":"📕","label":"El capital","text":"El tomo I arma la pieza técnica: <strong>el excedente lo produce el trabajo y se lo apropia el dueño</strong>. Es una tesis con definiciones, no un insulto: por eso se puede auditar, y por eso el panfleto la caricaturiza."},{"y":"S. XX","icon":"🏭","label":"El sistema con Estado","text":"La doctrina gobierna países. Su mejor expediente (la industrialización que <strong>Allen defiende con datos</strong>, los saltos de alfabetización, el cotejo de <strong>Sen</strong> en salud) entra al acero <strong>con etiqueta de disputa viva</strong>; los costos se pesarán en su módulo."},{"y":"1900s","icon":"🗣️","label":"Los dos púlpitos","text":"Siglo y medio de insulto y bandera: en esta vecindad la palabra exime de estudiar <strong>en las dos direcciones</strong>. Quien domina el acero deja de ser presa fácil de ambos púlpitos, y eso es una forma de libertad."},{"y":"Hoy","icon":"🎭","label":"La prueba de Turing","text":"Caplan propone el ejercicio: exponer la doctrina <strong>sin que un defensor te distinga</strong>. Etiqueta: divulgación útil, no medida validada. La casa la corre como estación primera de todo juicio."},{"y":"Esta etapa","icon":"🗝️","label":"La licencia","text":"<strong>Diez minutos de pie sin que un marxista corrija.</strong> Con la licencia ganada se abren las etapas que siguen: la calculadora, el tribunal, los tres expedientes. <strong>Sin licencia no hay juicio: hay eco.</strong>"}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(acero){sfx(acero?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(acero){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🛡️</span><span class="ms-text"><strong>La pieza salió con definiciones:</strong> «el excedente lo produce el trabajo y se lo apropia el dueño de los medios». La familia escuchó completo, y nadie pudo distinguir si Jael era de los suyos: eso era la prueba.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🗝️</span><span class="ms-text"><strong>La licencia quedó ganada:</strong> diez minutos de pie sin corrección. Ahora sí viene el juicio, con las etapas que siguen, y la primera crítica que Jael escriba tocará el sistema real, no un muñeco.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">✋</span><span class="ms-text"><strong>La mano se alzó, como estaba pactado:</strong> «roban y ya» no lo firmaría ningún defensor. No es reprobación: es la regla protegiendo la licencia. La defensa se detiene sin drama.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📚</span><span class="ms-text"><strong>Esa noche se revisa la pieza:</strong> la tesis con sus definiciones, que justo por eso se puede auditar. La defensa se repite otro día, y la licencia ganada a la segunda vale igual de entera.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"resumen":{"nombre":"El resumen fuerte","icon":"🛡️","estructura":{"title":"Qué es","info":"• Las cuatro piezas que un marxista firmaría:<br>• <strong>Materialismo histórico</strong> y <strong>explotación</strong><br>• <strong>Tendencia a la crisis</strong> y <strong>sociedad sin clases</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• Se enuncia <strong>en el vocabulario del defensor</strong>, sin comillas de burla<br>• Como programa de investigación, no como profecía<br>• Y con las definiciones puestas: <strong>por eso se puede auditar</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• «Roban y ya»: la pieza difícil <strong>vuelta insulto</strong><br>• El paraíso vago: la promesa <strong>vuelta chiste</strong><br>• Releer los enteros que ya cursaron <strong>sus materias dueñas</strong>"},"cuidados":{"title":"En esta casa","info":"• El resumen se escribe <strong>antes</strong> de toda crítica<br>• Se ensaya de pie, con reloj<br>• Y si suena a caricatura, <strong>se detiene y se repite otro día</strong>"}},"turing":{"nombre":"La prueba de Turing","icon":"🎭","estructura":{"title":"Qué es","info":"• El ejercicio de <strong>Bryan Caplan</strong>: exponer la doctrina ajena<br>• De modo que <strong>un defensor no te distinga</strong> de los suyos<br>• Etiqueta: <strong>divulgación útil, no medida validada</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• El vocabulario es el del defensor, <strong>en su sentido</strong><br>• La fuerza moral aparece documentada<br>• Y el cierre lo diría un defensor: <strong>«así es, eso sostengo»</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Burlas o comillas de desprecio <strong>a media frase</strong><br>• Confundir pasar la prueba con <strong>estar de acuerdo</strong><br>• Usarla como medida científica: <strong>es un ejercicio</strong>"},"cuidados":{"title":"En esta casa","info":"• Es la <strong>estación primera</strong> de todo juicio<br>• La fábrica de la herramienta vive en Estudio de las Ideologías<br>• Y se aplica <strong>a los dos púlpitos por igual</strong>"}},"fuerza":{"nombre":"La fuerza moral","icon":"⚖️","estructura":{"title":"Qué es","info":"• Lo que la crítica perezosa omite: <strong>Marx no vendía un cielo</strong><br>• Señalaba <strong>niños en minas</strong> con informes de inspectores ingleses<br>• Indignación documentada: <strong>explica siglo y medio de lealtades</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• Trae documento: <strong>los informes fabriles</strong>, con fecha<br>• Explica por qué gente seria creyó, <strong>sin volverla tonta</strong><br>• Y no suma en la calculadora: <strong>conmover no es demostrar</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Omitirla: el sistema queda como <strong>capricho sin causa</strong><br>• Confundirla con validez técnica: <strong>son libros distintos</strong><br>• Usarla de escudo contra toda auditoría"},"cuidados":{"title":"En esta casa","info":"• Entra al acero <strong>siempre</strong>, antes del expediente<br>• Se concede en voz alta sin firmar el sistema<br>• Y se separa del veredicto: <strong>la báscula pesa, no llora</strong>"}},"numeros":{"nombre":"Los números del acero","icon":"📊","estructura":{"title":"Qué es","info":"• El mejor expediente empírico que un defensor presentaría<br>• <strong>Allen (2003)</strong>: la industrialización, con datos<br>• <strong>Sen</strong>: salud básica China-India antes de la reforma"},"funcion":{"title":"Cómo se reconoce","info":"• Cada cifra con <strong>horquilla, método, fuente y fecha</strong><br>• Cada defensa con <strong>su etiqueta</strong>: disputa viva, académico sólido<br>• Y el dato que alegra, <strong>con doble auditoría</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• El número redondo <strong>de bandera</strong><br>• Poner solo los números que hunden, <strong>o solo los que salvan</strong><br>• Confundir poner en pie con <strong>absolver</strong>: pesar viene después"},"cuidados":{"title":"En esta casa","info":"• Se ponen en pie aquí, <strong>se pesan en los tres expedientes</strong><br>• La báscula es pareja: el expediente gemelo usa las mismas reglas<br>• Y ningún número entra <strong>sin su disputa nombrada</strong>"}}};
let labParte='resumen',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}


// ===================== PREGUNTAS DE LAS LECTURAS =====================
// Tres baterias sobre los cinco textos (normas 5-quater y 5-quinquies):
// comprension lectora (25, cinco por voz), completar (10) y analisis
// complejo (10, sin XP a proposito). Las respuestas se contestan con los
// textos delante: es un examen de lectura, no de memoria.
const lectComprensionBank=[
{"t":"Borges","q":"¿Qué única costumbre comparte la «dinastía secreta» de libros que el narrador descubre oyendo fichas de catálogo?","o":["a) Estar dedicados a bibliotecarios ciegos","b) Citarse constantemente entre sí","c) Haber sido quemados alguna vez","d) Darle al enemigo las mejores armas antes de combatirlo"],"c":3},
{"t":"Borges","q":"Según el cuento, ¿cómo empieza cada artículo de la Suma de teología?","o":["a) Con una oración en latín","b) Con las objeciones: las razones más fuertes que parecen probar lo contrario de lo que el santo va a sostener","c) Con un resumen del artículo anterior","d) Con la respuesta, y las objeciones al final"],"c":1},
{"t":"Borges","q":"¿Qué regla privada confiesa Darwin en su Autobiografía, y por qué la seguía?","o":["a) Anotar de inmediato todo hecho que contradijera su teoría, porque esos hechos son los que la memoria se apresura a perder","b) Leer solo a sus partidarios para no distraerse","c) Publicar únicamente los datos favorables","d) Esperar diez años antes de publicar cualquier idea"],"c":0},
{"t":"Borges","q":"¿Por qué Böhm-Bawerk esperó hasta 1896 para publicar su crítica al sistema de Marx?","o":["a) Porque la censura de su país se lo impedía","b) Porque Hilferding todavía no le respondía","c) Porque no quiso dictar sentencia sin leer el tomo tercero de El capital, póstumo, que Engels publicó en 1894","d) Porque esperaba conocer a Marx en persona"],"c":2},
{"t":"Borges","q":"Según el narrador, ¿por qué se sigue leyendo el duelo entre Böhm-Bawerk e Hilferding más de un siglo después?","o":["a) Porque sus conclusiones ya nadie las disputa","b) Por su rareza: es uno de los pocos combates de su época en que los dos adversarios se habían leído","c) Porque los dos llegaron al mismo veredicto","d) Porque fue el pleito más insultante de su siglo"],"c":1},
{"t":"Cervantes","q":"¿Sobre qué daban voces los dos bachilleres de Salamanca en la venta?","o":["a) Sobre el tuyo y el mío: si los bienes debían ser comunes o si quitar la propiedad quitaba el trabajo y la hacienda","b) Sobre cuál universidad era mejor","c) Sobre el precio del vino de la cena","d) Sobre si la venta era castillo o venta"],"c":0},
{"t":"Cervantes","q":"¿Qué condición puso don Quijote antes de sentenciar el pleito?","o":["a) Que los bachilleres pagaran la cena","b) Que Sancho hiciera de juez","c) Que cada uno se hiciera armero de su enemigo: repetir las razones del otro tan cumplidamente que su dueño dijera «así es»","d) Que la disputa se resolviera con una batalla"],"c":2},
{"t":"Cervantes","q":"¿Qué entendió Sancho al oír hablar de aceros y arneses?","o":["a) Que don Quijote quería sentenciar sin cobrar","b) Que los bachilleres eran caballeros andantes","c) Que había que llamar al ventero","d) Que la disputa acabaría en batalla verdadera, y quiso alquilarles la celada de su señor por dos reales y el vino de la cena"],"c":3},
{"t":"Cervantes","q":"¿Qué hallaron los bachilleres cuando probaron a decir las razones del contrario?","o":["a) Que se las sabían de memoria","b) Que no las sabían, con haberlas combatido toda la tarde, y de la vergüenza nació la mansedumbre","c) Que el otro había cambiado de opinión","d) Que don Quijote las había inventado"],"c":1},
{"t":"Cervantes","q":"Según la sentencia final de don Quijote, ¿qué no teme la verdad y qué le pasa a la mentira?","o":["a) La verdad no teme al ventero, y la mentira paga los jarros","b) La verdad teme las lanzas y la mentira las esquiva","c) La verdad no teme lanzas enteras, y la mentira ni aun con el rival desarmado duerme segura","d) La verdad duerme segura y la mentira no duerme jamás"],"c":2},
{"t":"Harari","q":"¿Qué truco aprendieron nuestros antepasados hace unos setenta mil años, según el ensayo?","o":["a) A domesticar el fuego","b) A creer juntos en cosas que no se pueden tocar, lo que permite que millones de extraños cooperen","c) A cultivar trigo","d) A escribir en tablillas de barro"],"c":1},
{"t":"Harari","q":"¿Con qué dato muestra el ensayo el poder de la historia marxista?","o":["a) Fue el primer libro traducido a cien idiomas","b) Su autor llegó a gobernar tres países","c) Vendió mil millones de ejemplares en un siglo","d) Empezó en 1848 como un folleto de unas pocas decenas de páginas y ciento veinte años después cerca de un tercio de la humanidad vivía bajo gobiernos que se declaraban sus herederos"],"c":3},
{"t":"Harari","q":"¿Qué halló el estudio del MIT publicado en Science en 2018 sobre unas ciento veintiséis mil cadenas de noticias?","o":["a) Que las falsas tenían un setenta por ciento más de probabilidades de ser compartidas y llegaban unas seis veces más rápido","b) Que las verdaderas viajaban más rápido pero menos lejos","c) Que solo los robots difundían noticias falsas","d) Que las noticias falsas eran menos del uno por ciento del total"],"c":0},
{"t":"Harari","q":"¿Qué es la prueba de Turing ideológica que Caplan nombró en 2011, según el ensayo?","o":["a) Un examen universitario de economía","b) Una medida científica validada de imparcialidad","c) Exponer la doctrina ajena hasta que sus fieles no puedan distinguirte de uno de ellos: no es cortesía, es control de calidad","d) Un test para distinguir robots de personas"],"c":2},
{"t":"Harari","q":"Según el cierre del ensayo, ¿qué regla separará a quienes decidan bien de quienes decidan a ciegas en el siglo veintiuno?","o":["a) Saber programar inteligencia artificial","b) No creer en ninguna historia compartida","c) Compartir solo noticias verificadas","d) La capacidad de habitar la historia del otro sin ser poseído por ella"],"c":3},
{"t":"Entrevista","q":"¿Dónde sitúa la entradilla el encuentro con Marx, y qué detalle da de su vida ahí?","o":["a) En su casa de Tréveris, rodeado de discípulos","b) En la redacción de la Gaceta Renana, en Colonia","c) En la sala de lectura del Museo Británico, donde pasó años escribiendo El capital mientras en su casa faltaba el pan","d) En un café de París, con Engels al lado"],"c":2},
{"t":"Entrevista","q":"¿Cuáles son las cuatro piezas que, según Marx, un crítico honrado debe saber enunciar de pie?","o":["a) El materialismo histórico como programa, la teoría de la explotación con su excedente, la tendencia a la crisis y la promesa de la sociedad sin clases","b) La plusvalía, la dialéctica, la revolución y el partido","c) La economía, la política, la historia y la filosofía","d) El Manifiesto, El capital, la Gaceta Renana y los informes fabriles"],"c":0},
{"t":"Entrevista","q":"¿Qué responde Marx cuando Scherer le dice que su doctrina nació de la envidia?","o":["a) Que la envidia es un motor tan legítimo como otro","b) Que nació de los informes de los inspectores fabriles ingleses, con niños en las minas: él no inventó ese dolor, lo citó con fecha y número de informe, y la envidia no redacta notas al pie","c) Que Scherer no tiene derecho a preguntar eso","d) Que la envidia era de sus rivales, no suya"],"c":1},
{"t":"Entrevista","q":"¿Qué elogio del Manifiesto de 1848 recuerda Marx como su propio ejercicio de acero?","o":["a) Que los obreros eran los mejores lectores de Europa","b) Que Inglaterra tenía las mejores fábricas del mundo","c) Que Engels era el mejor economista de su tiempo","d) Que la burguesía levantó maravillas mayores que las pirámides de Egipto, los acueductos romanos y las catedrales góticas"],"c":3},
{"t":"Entrevista","q":"¿Qué le pide Marx al final al muchacho que va a juzgarlo, y con qué condición de aduana?","o":["a) Que lo ponga de pie entero, con su mejor acero, y después lo audite sin piedad; con la condición de que el dato que lo alegre pague doble revisión antes de entrar al cuaderno","b) Que lea el Manifiesto y firme sin discutir","c) Que no lo juzgue nunca, porque ya lo juzgó la historia","d) Que se haga discípulo antes que juez"],"c":0},
{"t":"Quintero y Gala","q":"¿Qué dato trae Quintero sobre la Suma de teología de Tomás de Aquino?","o":["a) Que se escribió en Córdoba","b) Que se escribió entre 1265 y 1274 y que cada artículo empieza con las razones más fuertes del bando contrario","c) Que fue prohibida por la censura de su siglo","d) Que tiene exactamente mil artículos"],"c":1},
{"t":"Quintero y Gala","q":"¿En qué imagen convierte Gala la regla de Aquino?","o":["a) En un juez que dicta dos sentencias a la vez","b) En un jardinero que cuida espantapájaros","c) En un sastre bueno que le toma las medidas exactas al enemigo y le corta un traje digno, y solo después discute con él","d) En un bailarín que ensaya sin música"],"c":2},
{"t":"Quintero y Gala","q":"¿Qué cifras del estudio del MIT en Science (2018) susurra Quintero?","o":["a) Mil cadenas de noticias y un diez por ciento más de mentiras","b) Un millón de mensajes y el doble de velocidad","c) Cien mil noticias, todas falsas","d) Ciento veintiséis mil cadenas de noticias: las falsas se compartían un setenta por ciento más y corrían seis veces más rápido"],"c":3},
{"t":"Quintero y Gala","q":"¿Qué aprendió Gala en el teatro, según cuenta a propósito de «Anillos para una dama» (1973)?","o":["a) Que una obra se muere en el segundo acto si el autor no le escribe al antagonista sus mejores parlamentos","b) Que el público prefiere villanos torpes","c) Que los estrenos se ganan con música","d) Que el antagonista debe aparecer lo menos posible"],"c":0},
{"t":"Quintero y Gala","q":"¿Con qué aforismo cierra Gala la conversación?","o":["a) «El que mucho abarca poco aprieta»","b) «La verdad no teme lanzas enteras»","c) «Solo tiene derecho a apagar una idea quien fue capaz de encenderla entera»","d) «Ningún viento es favorable para el que no sabe adónde va»"],"c":2}];
